package tv.own.owntv.core.brand

import androidx.annotation.DrawableRes
import androidx.annotation.StringRes
import tv.own.owntv.core.R

/**
 * The six colours of the OwnTV flip-card icon and logo. Every drawable here is
 * generated by `tools/brand/render_brand.py`.
 *
 * Each colour is its own launcher activity in the host app: `MainActivity` + [activitySuffix]. Eggshell, the
 * default, is `MainActivity` itself, so a home-screen icon from before this feature keeps working on upgrade.
 */
enum class AppIcon(
    val activitySuffix: String,
    @StringRes val label: Int,
    /** Flat in-app mark, cropped to the card: the sidebar, lockups, About. */
    @DrawableRes val mark: Int,
    /** The simpler drawing for 32 dp and below. */
    @DrawableRes val markSmall: Int,
    /** 320×180 Android TV banner, also the logo of the TV home-screen channel. */
    @DrawableRes val banner: Int,
    /** ARGB of the wordmark's "TV" on a dark surface. */
    val accent: Long,
) {
    PETROL("Petrol", R.string.app_icon_petrol, R.drawable.owntv_mark_petrol, R.drawable.owntv_mark_small_petrol, R.drawable.owntv_banner_petrol, 0xFF5CC2BC),
    SUNFLOWER("Sunflower", R.string.app_icon_sunflower, R.drawable.owntv_mark_sunflower, R.drawable.owntv_mark_small_sunflower, R.drawable.owntv_banner_sunflower, 0xFFFFD24D),
    COBALT("Cobalt", R.string.app_icon_cobalt, R.drawable.owntv_mark_cobalt, R.drawable.owntv_mark_small_cobalt, R.drawable.owntv_banner_cobalt, 0xFF8AAAFF),
    TOMATO("Tomato", R.string.app_icon_tomato, R.drawable.owntv_mark_tomato, R.drawable.owntv_mark_small_tomato, R.drawable.owntv_banner_tomato, 0xFFFF9C84),
    BOARD("Board", R.string.app_icon_board, R.drawable.owntv_mark_board, R.drawable.owntv_mark_small_board, R.drawable.owntv_banner_board, 0xFF52DBC8),
    EGGSHELL("", R.string.app_icon_eggshell, R.drawable.owntv_mark_eggshell, R.drawable.owntv_mark_small_eggshell, R.drawable.owntv_banner_eggshell, 0xFF86D3DB),
    OLIVE("Olive", R.string.app_icon_olive, R.drawable.owntv_mark_olive, R.drawable.owntv_mark_small_olive, R.drawable.owntv_banner_olive, 0xFFA5CC4E),
    OLIVE_CREAM("OliveCream", R.string.app_icon_olive_cream, R.drawable.owntv_mark_olive_cream, R.drawable.owntv_mark_small_olive_cream, R.drawable.owntv_banner_olive_cream, 0xFFA5CC4E),

    // Pixel, drawn by `render_brand.py stage`: the TV set as a dot matrix.
    PIXEL("Pixel", R.string.app_icon_pixel, R.drawable.owntv_mark_pixel, R.drawable.owntv_mark_small_pixel, R.drawable.owntv_banner_pixel, 0xFF52DBC8);

    /**
     * Whether the drawing at this size is the flip card, whose play triangle sits exactly where
     * `owntv_mark_play` / `owntv_mark_play_small` draw it, so an app can tint it with the accent. Pixel's
     * large mark is dots (an app draws its triangle itself); its small mark is the card.
     */
    fun isCard(small: Boolean): Boolean = small || this != PIXEL

    companion object {
        val DEFAULT = EGGSHELL

        fun fromStored(value: String?): AppIcon = entries.firstOrNull { it.name == value } ?: DEFAULT
    }
}
